import{_ as t,o,c as a,a2 as i}from"./chunks/framework.CnJ-JtFX.js";const u=JSON.parse('{"title":"EP.11 事件联动三种打法：comp / code / data-source","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.11-tmagic-advanced.md","filePath":"comics/EP.11-tmagic-advanced.md","lastUpdated":1792683644000}'),s={name:"comics/EP.11-tmagic-advanced.md"};function c(n,e,d,r,l,p){return o(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="ep-11-事件联动三种打法-comp-code-data-source" tabindex="-1">EP.11 事件联动三种打法：comp / code / data-source <a class="header-anchor" href="#ep-11-事件联动三种打法-comp-code-data-source" aria-label="Permalink to &quot;EP.11 事件联动三种打法：comp / code / data-source&quot;">​</a></h1><blockquote><p>对应章节：<a href="./../guide/11-tmagic-advanced">guide/11-tmagic-advanced</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ol><li><strong>困境</strong>：运营要求一个按钮&quot;点了能弹窗、能让另一个组件翻面、能刷新数据源&quot;，标签君试图在一个 Vue 组件里写三个 click listener。</li><li><strong>揭秘</strong>：码叔把三种联动方式列在一张卡片上——CODE 执行 DSL 里预定义的 codeBlock，COMP 调目标组件的 instance method，DATA_SOURCE 调数据源的 setData / request。</li><li><strong>实证</strong>：像素酱在画布上点了按钮，弹窗弹出来 → 动画卡翻了一面 → 柱状图刷新了数据。</li><li><strong>结案</strong>：码叔收束到「EventHelper 统一 dispatch，三种 actionType 只是 switch 分支」——理解链路，比记住 API 更重要。</li></ol><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第一格-一个按钮三种联动" tabindex="-1">第一格：一个按钮三种联动 <a class="header-anchor" href="#第一格-一个按钮三种联动" aria-label="Permalink to &quot;第一格：一个按钮三种联动&quot;">​</a></h3><p>按钮点一下想干三件事——<strong>串行 await 执行</strong>、<strong>flowState 可中断</strong>。EventHelper 在 dispatch 时按顺序遍历 actions 数组，每个 actionType 对应一个 switch 分支：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">async </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">actionHandler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(actionItem, fromCpt, args, flowState) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (actionItem.actionType </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ActionType.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">COMP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  else</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (actionItem.actionType </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ActionType.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">CODE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  else</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (actionItem.actionType </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ActionType.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DATA_SOURCE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>所以三件事必须同属于一个 <code>actions: [...]</code> 数组，按顺序写在前一个之后。如果想条件跳过（比如 stock &gt; 0 才弹窗），把条件写进 code block 里，或用 <code>flowState.abort()</code> 在 CODE 里中断后续 COMP 和 DATA_SOURCE。</p><p>对应正文：<a href="./../guide/11-tmagic-advanced#事件联动三种-action">原理拆解 · 事件联动三种 Action</a>。</p><h3 id="第二格-组件四件套" tabindex="-1">第二格：组件四件套 <a class="header-anchor" href="#第二格-组件四件套" aria-label="Permalink to &quot;第二格：组件四件套&quot;">​</a></h3><p>写一个业务组件不是&quot;写一个 Vue 文件&quot;那么简单——四件套决定了：</p><table tabindex="0"><thead><tr><th>文件</th><th>决定什么</th><th>被谁用到</th></tr></thead><tbody><tr><td>index.vue</td><td>运行时渲染 + 事件 emit</td><td>runtime 的 App 实例</td></tr><tr><td>formConfig</td><td>编辑器右侧表单有哪些字段</td><td>编辑器 propsConfigs[type]</td></tr><tr><td>initValue</td><td>新组件拖入画布时的 DSL 值</td><td>编辑器 propsValues[type]</td></tr><tr><td>event</td><td>可触发的事件名 + 对外暴露的方法</td><td>eventMethodList[type]</td></tr></tbody></table><p>lab 里 AnimatedCard 在 <code>onMounted</code> 里把 <code>flip</code> 方法挂到 <code>node.instance.flip = flip</code>——这步是 COMP 联动能调通的关键。声明了 methods 数组但没实际挂方法，联动静默跳过，也不报错。</p><h3 id="第三格-数据源四件套" tabindex="-1">第三格：数据源四件套 <a class="header-anchor" href="#第三格-数据源四件套" aria-label="Permalink to &quot;第三格：数据源四件套&quot;">​</a></h3><p>数据源比组件多一个 <code>dataSource</code> 类：它继承 <code>@tmagic/data-source.DataSource</code>（静态基类）或 <code>HttpDataSource</code>（HTTP 基类），重写 <code>get type()</code> 和 <code>init()</code>。<code>DataSourceManager.register(type, cls)</code> 在 runtime <code>new TMagicApp</code> 之前或组件 import 后立即调用即可。</p><p>组件里想引用数据源字段，formConfig 写 <code>{ type: &quot;data-source-field-select&quot; }</code>，编辑器会弹出数据源选择器；运行时 core 的 <code>compiledNode</code> 会把 <code>config.fields.xxx</code> 自动替换成真实数据。</p><h3 id="第四格-发布链路为什么走-cli" tabindex="-1">第四格：发布链路为什么走 CLI <a class="header-anchor" href="#第四格-发布链路为什么走-cli" aria-label="Permalink to &quot;第四格：发布链路为什么走 CLI&quot;">​</a></h3><p>tmagic 官方有 <code>@tmagic/cli</code>，命令是 <code>tmagic entry</code>——它扫 <code>tmagic.config.ts</code> 的 packages 列表，把每个组件的 formConfig / initValue / event 拼成一份 UMD（<code>config-entry.js</code> / <code>value-entry.js</code> / <code>event-entry.js</code> / <code>ds-config-entry.js</code> / <code>ds-value-entry.js</code>），编辑器通过 <code>asyncLoadJs</code> 异步加载这五份，自动回填 propsConfigs / propsValues / eventMethodList / datasourceConfigs / datasourceValues。</p><p>lab 跳过了这步，手动 import + 手动回填——因为体量小、手动更可控。但如果你要做真正的发布流水线（runtime 一个工程，编辑器一个工程），cli 是标准做法。</p><h2 id="逐格解读" tabindex="-1">逐格解读 <a class="header-anchor" href="#逐格解读" aria-label="Permalink to &quot;逐格解读&quot;">​</a></h2><h3 id="第一格-一个按钮三种联动-1" tabindex="-1">第一格：一个按钮三种联动 <a class="header-anchor" href="#第一格-一个按钮三种联动-1" aria-label="Permalink to &quot;第一格：一个按钮三种联动&quot;">​</a></h3><p><strong>画面</strong>：画布上有一个&quot;多功能按钮&quot;组件，旁边飘着三个箭头：① 弹窗（alert 图标）；② 翻面（卡片图标）；③ 柱状图刷新（柱状图 + 刷新图标）。箭头根部连着 DSL 的 <code>actions: [CODE, COMP, DATA_SOURCE]</code> 数组。</p><p><strong>台词</strong>：</p><blockquote><p>像素酱：「按钮点一下能调三个东西？」 码叔：「对，串行跑；flowState.abort 能中途停。」</p></blockquote><h3 id="第二格-组件四件套-1" tabindex="-1">第二格：组件四件套 <a class="header-anchor" href="#第二格-组件四件套-1" aria-label="Permalink to &quot;第二格：组件四件套&quot;">​</a></h3><p><strong>画面</strong>：四个带编号的卡片：① index.vue（运行时本体）；② formConfig（右侧表单）；③ initValue（拖入默认 DSL）；④ event（事件 / 方法声明）。第四张卡片上有一条虚线指向 <code>node.instance.flip = flip</code> 的代码行。</p><p><strong>台词</strong>：</p><blockquote><p>码叔：「声明了 methods 不够，要真把方法挂 instance 上。不然联动调的是 undefined。」</p></blockquote><h3 id="第三格-数据源四件套-1" tabindex="-1">第三格：数据源四件套 <a class="header-anchor" href="#第三格-数据源四件套-1" aria-label="Permalink to &quot;第三格：数据源四件套&quot;">​</a></h3><p><strong>画面</strong>：一个 HttpDataSource 类，旁边 formConfig 里有 <code>{ type: &quot;data-source-field-select&quot; }</code> 字段；下面是 <code>DataSourceManager.register(&quot;my-http&quot;, MyDataSource)</code>；再下方是组件里价格字段自动变成真实数据的箭头。</p><p><strong>台词</strong>：</p><blockquote><p>像素酱：「哦原来 data-source-field-select 是 formConfig type，不是 DSL 里随便写的！」</p></blockquote><h3 id="第四格-发布链路" tabindex="-1">第四格：发布链路 <a class="header-anchor" href="#第四格-发布链路" aria-label="Permalink to &quot;第四格：发布链路&quot;">​</a></h3><p><strong>画面</strong>：<code>tmagic.config.ts</code> → <code>tmagic entry</code> → 五份 .js（config / value / event / ds-config / ds-value）→ 编辑器 runtimeUrl + <code>/entry/config.js</code> 异步加载。旁边有一个&quot;lab 简化版&quot;的虚线框，指向手动 import + 手动回填。</p><p><strong>台词</strong>：</p><blockquote><p>码叔：「完整发布走 cli；lab 跳过，手动 import 更可控。」</p></blockquote><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><ol><li><strong>COMP 联动调不动 flip，控制台不报错</strong> — 声明 methods 数组只是让编辑器右侧面板能选到 flip 这个名字；真正要调通，必须在组件 <code>onMounted</code> 里 <code>node.instance.flip = flip</code> 显式挂方法。没挂的话 EventHelper 调时会静默跳过，也不报错。</li><li><strong>CODE action 执行静默跳过</strong> — 在 code block 的 content 里抛 <code>throw new Error(&quot;hello from code block&quot;)</code> 看 console，就能知道有没有执行到；也可临时在 EventHelper.actionHandler 里打 log。静默跳过通常是 codeId 写错或前一个 action 用 flowState.abort 中断了。</li><li><strong>数据源 register 了但编辑器找不到</strong> — <code>DataSourceManager.register(type, cls)</code> 必须在 <code>new TMagicApp({...})</code> <strong>之前</strong>或组件 import <strong>之后立即</strong> 调，不能等到 useDsl / useEditorDsl 初始化后。初始化后再注册，编辑器左侧数据源面板已经构建完列表，不会再刷新。</li><li><strong>formConfig type 收窄过严 TS 报错</strong> — 把 <code>propsConfigs</code> 的类型声明改成 <code>any[]</code> 绕过。运行时 <code>@tmagic/form</code> 支持更多 type（color-picker、boolean、rate、slider、date-picker 等），但 TS 的 FormItemConfig 类型联合没完全覆盖。官方 playground 也是 <code>as any</code>。</li><li><strong>style 字段写了 <code>left: 30</code> 没单位</strong> — 必须 <code>left: &quot;30px&quot;</code> 或 <code>left: &quot;30%&quot;</code>。数字在 CSS 里是非法单位值，画布的绝对定位布局会错乱。initValue 里直接写字符串即可，编辑器不会自动帮你补单位。</li><li><strong>自定义 type 和 runtime register key 不一致</strong> — componentGroupList / propsConfigs / propsValues / eventMethodList 里用的 type 和 <code>app.registerComponent(type, Component)</code> 的 key 必须严格一致。有一处错，画布就渲染不出来（resolveComponent 返回 undefined）。</li></ol><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>1. 自定义组件四件套（index.vue / formConfig / initValue / event）分别决定什么？lab 为什么手动 import + 手动回填而不用 @tmagic/cli？</b></summary><p>四件套分工：</p><ul><li><code>index.vue</code>：运行时渲染本体 + 组件内部逻辑 + event emit（<code>magic:common:events:click</code> 等）；</li><li><code>formConfig.ts</code>：编辑器右侧属性面板有哪些字段（type/text/name 数组，支持 text / color-picker / data-source-input / data-source-field-select 等）；</li><li><code>initValue.ts</code>：新组件拖入画布时的初始 DSL 值（节点的默认 title / style / barColor 等）；</li><li><code>event.ts</code>：组件可触发的事件名（events 数组）和对外暴露的方法名（methods 数组）——编辑器右侧&quot;事件联动&quot;面板作为源 / 目标选项。</li></ul><p>lab 跳过 cli 的原因：<strong>体量小、手动更可控</strong>。cli 的 <code>tmagic entry</code> 会把每个组件的四件套拼成五份 UMD（config / value / event / ds-config / ds-value），编辑器通过 <code>asyncLoadJs(runtimeUrl + &quot;/entry/config.js&quot;)</code> 异步加载后自动回填 propsConfigs / propsValues / eventMethodList / datasourceConfigs / datasourceValues。但 lab 只有 5 个组件，手动 import + 手动回填两行代码就搞定，引入 cli 的工程开销（tmagic.config.ts、.tmagic/ 目录、build:page / build:libs / build:playground 三条命令）远大于收益。真正做发布流水线时再走 cli。</p></details><details><summary><b>2. EventHelper 的三种 actionType（CODE / COMP / DATA_SOURCE）分别做什么？执行模型是怎样的？flowState 在中间扮演什么角色？</b></summary><p>三种 actionType 共用同一个 DSL.events[].actions[] 数组，EventHelper.actionHandler 内部 switch 分支，<strong>串行 await 执行</strong>：</p><ul><li><strong>CODE</strong>：调 <code>app.runCode(codeId, params)</code>，找到 DSL 的 codeBlocks[codeId].content 函数，传入 <code>{ app, params, dataSource, eventParams, flowState }</code> 执行。code block 里可以调 app 的任何方法，甚至直接改其他节点的 DSL。</li><li><strong>COMP</strong>：调 <code>app.getNode(to).instance[methodName](fromCpt, ...args)</code>。to 是目标组件 id，methodName 是组件 methods 数组里声明的名字。核心前提是目标组件真的在 node.instance 上挂了这个方法。</li><li><strong>DATA_SOURCE</strong>：先查 <code>dataSource.methods</code> 数组里有没有同名方法（code block 形式），有就执行；没有就 fallback 到 <code>dataSource[methodName]({ params })</code>（类方法形式，如 request / setData）。</li></ul><p><strong>flowState</strong>：所有 action 共享同一个 flowState 对象，三个方法——<code>abort()</code> 中断后续所有 action、<code>reset()</code> 在所有 action 跑完后自动调、<code>get</code> / <code>set</code> 可以在多个 action 间共享中间状态。用 <code>abort()</code> 就能实现&quot;条件联动&quot;——比如 stock &lt;= 0 时第一个 CODE action 直接 abort，后面的 COMP 翻卡片、DATA_SOURCE 刷新都不执行。</p></details><details><summary><b>3. tmagic 的数据源模型是什么？组件里想用数据源字段，formConfig 和 runtime 各要做什么？</b></summary><p><strong>数据源模型</strong>：@tmagic/data-source 提供基类 DataSource（静态数据源）和 HttpDataSource（继承它，加 url / method / headers / responseOptions / beforeRequest / afterResponse）。自定义数据源要：</p><ol><li>继承其中一个基类；</li><li>重写 <code>get type()</code> 返回唯一字符串（不能用 static / http，tmagic 内置已占用）；</li><li>实现 <code>init()</code>（HttpDataSource.init() 内部自动调 request()）；</li><li>重写 <code>formConfig</code> / <code>initValue</code> / <code>event</code> 描述编辑器里能改什么。</li></ol><p><strong>formConfig 侧</strong>：组件的 formConfig 里写 <code>{ type: &quot;data-source-input&quot;, name: &quot;price&quot; }</code> 或 <code>{ type: &quot;data-source-field-select&quot;, name: &quot;priceField&quot; }</code>。data-source-input 让编辑器弹出&quot;静态值 / 数据源模板&quot;切换的输入框；data-source-field-select 直接从已注册数据源里选一个字段。</p><p><strong>runtime 侧</strong>：<code>DataSourceManager.register(type, MyDataSource)</code> 必须在 <code>new TMagicApp({...})</code> 之前调，否则编辑器数据源面板初始化时扫不到。组件 DSL 的 config.price 字段会被 core 的 <strong>compiledNode</strong> 自动编译——如果值是数据源模板字符串（如 <code>&amp;#123;&amp;#123;ds_1.data.price&amp;#125;&amp;#125;</code>），运行时 compiledNode 会把它替换成真实数据，组件渲染时直接拿到最终值，不用手动 watch。</p></details>`,43)])])}const g=t(s,[["render",c]]);export{u as __pageData,g as default};
